; A bakery in Questeria: two ovens going in the back wall on the bakehouse's flagstones, the pans on
; their rack, the kneading table and the sacks of flour, and the counter across the shop with the baker
; behind it and a customer in front. Every bakery that's this one inside comes back out its own door.

[map]
id = bakery
name = The Bakery
tileset = interior
size = 16 11
dark = yes
ambient = 0.65
fog = no
music = Exploring

[legend]
- = floor-wood
s = floor-stone
r = rug
# = wall-top
| = wall-face
_ = wall-base

